// Cockpit voice warnings: which call-out to speak and when, kept free of Web Audio so it can be tested in node.
// Clips live in public/audio/voice/<style>/<key>.mp3 (generated by tools/make-voices.py).

export const VOICE_STYLES = {
  betty: 'US fighter (female, "Pull up")',
  gpws: 'US airliner GPWS (male, "Terrain, pull up")',
  rita: 'Russian fighter (Su-27 style, Russian phrases)',
};
export const DEFAULT_VOICE_STYLE = 'betty';

// highest priority first; a higher one interrupts a lower one mid-sentence
export const VOICE_KEYS = ['pullUp', 'stall', 'overG', 'overspeed', 'gearUnsafe', 'lowFuel'];

// silence after a call-out before it repeats while the warning stays active, seconds
export const VOICE_REPEAT = { pullUp: 0.3, stall: 0.7, overG: 1.5, overspeed: 3, gearUnsafe: 3.5, lowFuel: 30 };

// a warning must stay clear this long before a re-trigger speaks at once (stall buffet flickers on and off)
const RESET_AFTER = 1.5;

export const voiceStyle = (s) => (Object.prototype.hasOwnProperty.call(VOICE_STYLES, s) ? s : DEFAULT_VOICE_STYLE);
export const voiceUrl = (base, style, key) => `${base}audio/voice/${voiceStyle(style)}/${key}.mp3`;

export class VoiceScheduler {
  constructor() { this.reset(); }

  reset() {
    this.playing = null; this.until = 0;
    this.nextAt = Object.create(null); this.clearSince = Object.create(null);
  }

  // warn: { pullUp, stall, ... } booleans; now: seconds; duration(key): clip length in seconds, or 0 when not loaded.
  // Returns { key, interrupt } for a clip to start now, or null.
  step(warn, now, duration) {
    if (this.playing && now >= this.until) this.playing = null;
    let best = null;
    for (const key of VOICE_KEYS) {
      if (warn && warn[key]) {
        this.clearSince[key] = undefined;
        if (!best && duration(key) > 0) best = key;
      } else {
        if (this.clearSince[key] === undefined) this.clearSince[key] = now;
        else if (now - this.clearSince[key] >= RESET_AFTER) this.nextAt[key] = 0;
      }
    }
    if (!best) return null;
    let interrupt = false;
    if (this.playing) {
      if (VOICE_KEYS.indexOf(best) >= VOICE_KEYS.indexOf(this.playing)) return null;
      interrupt = true;
    } else if (now < (this.nextAt[best] || 0)) {
      return null;
    }
    const len = duration(best);
    this.playing = best; this.until = now + len; this.nextAt[best] = now + len + VOICE_REPEAT[best];
    return { key: best, interrupt };
  }

  // the clip in progress, for ducking the warning tones underneath it
  speaking(now) { return !!this.playing && now < this.until; }
}
